import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";

const sourcePath = "cloud/kernels/A_v3.2.18.source.md";
const expectedHash = "a12017250c9b6ee82c32916f15952e163e042475d47a14a0709cea5d1d1394f4";
const source = readFileSync(new URL("./kernels/A_v3.2.18.source.md", import.meta.url));
if (createHash("sha256").update(source).digest("hex") !== expectedHash) {
  throw new Error("A v3.2.18 原文基线校验失败；请恢复原文，不要静默修改基线。");
}
const adapter = readFileSync(new URL("./kernels/fidelity.cloud.md", import.meta.url), "utf8").replace(/\r\n/g, "\n");
const divider = "## 编译与执行适配";
if (!adapter.includes(divider) || adapter.length > 9000) throw new Error("云端适配合同结构或长度无效");

export const KERNEL_SOURCE = Object.freeze({
  version: "3.2.18", sha256: expectedHash, bytes: source.length, sourcePath,
  adapterRevision: "cloud-visual-view-choice-v2",
  adapterSha256: createHash("sha256").update(adapter).digest("hex"),
});
export const WEARABLE_GENERATION_RULES = adapter.slice(0, adapter.indexOf(divider)).trim();
export const WEARABLE_COMPILE_RULES = adapter.slice(adapter.indexOf(divider)).trim();
export const KERNEL_CAPABILITIES = Object.freeze({
  reference_analysis: "timestamped_rgb_samples_or_template_timeline",
  depth: "not_available", pose: "not_available", segmentation_mask: "not_available", optical_flow: "not_available",
  identity_pixel_sanitization: "not_implemented", pixel_preservation: "not_guaranteed",
  visual_acceptance: "independent_vision_preflight_required",
  final_video_review: "opt_in_sampled_only",
});

// Metadata is generated by the server, not copied from the model's QA claims.
export function compileRevision(inputFingerprint, kernelSha256) {
  return "cloud-" + createHash("sha256").update(JSON.stringify([inputFingerprint, kernelSha256])).digest("hex").slice(0, 24);
}
